// WRONG: Vue reactivity in capability
import { ref } from 'vue';

export function createTasksCapability() {
  const tasks = ref<Task[]>([]);  // Forbidden!
  return { tasks };
}

// CORRECT: Plain TypeScript capability
export function createTasksCapability(): TasksCapability {
  return {
    listTasks: (path: string) => window.electronAPI.listTasks(path)
  };
}

// Vue reactivity belongs in orchestrator
import { shallowRef } from 'vue';

export function createAppOrchestrator(deps: { tasksCapability: TasksCapability }) {
  const tasks = shallowRef<Task[]>([]);

  async function refreshTasks(path: string) {
    tasks.value = await deps.tasksCapability.listTasks(path);
  }

  return { tasks, refreshTasks };
}

// WRONG: Raw provide/inject without type safety
const APP_KEY = Symbol('app');
provide(APP_KEY, appState);
const app = inject(APP_KEY);  // Type is unknown!

// CORRECT: Use createContext
const [injectApp, provideApp, APP_KEY] = createContext<AppState>('App');
provideApp(appState);
const app = injectApp();  // Fully typed, throws if missing
